contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 depositAmt, uint256 withdrawAmt) public payable {
        require(address(this).balance >= depositAmt);
        c.deposit{value: depositAmt}();
        c.refund();
        bool reverted;
        try c.withdraw(withdrawAmt) { reverted = false; }
        catch { reverted = true; }
        assert(withdrawAmt == 0 ? !reverted : reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        uint256 beforeC = address(c).balance;
        c.deposit{value: amount}();
        uint256 afterDeposit = address(c).balance;
        uint256 beforeThis = address(this).balance;
        c.refund();
        assert(beforeC + amount == afterDeposit && address(c).balance == 0 && address(this).balance == beforeThis + amount);
    }
    receive() external payable {}
}

